private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    byte octet = bb.get(i++);
    if (octet >= 0 && octet <= 7) {
        sb.append((char) octet);
        return i;
    } else if (octet == 8) {
        byte high = bb.get(i++);
        byte low = bb.get(i++);
        int value = ((high & 0xFF) << 8) | (low & 0xFF);
        sb.append((char) value);
        return i;
    } else {
        // Invalid octet
        sb.append((char) octet);
        return i;
    }
}

