void insertBefore(Bucket bucket) {
    Bucket temp = head;
    if (bucket == null || head == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }
    if (bucket == head) {
        bucket.next = head;
        head = bucket;
    } else {
        while (temp.next != null && temp.next != bucket) {
            temp = temp.next;
        }
        if (temp.next == null) {
            throw new IllegalArgumentException("Bucket not found in the list");
        }
        bucket.next = temp.next;
        temp.next = bucket;
    }
}

