public class BoxSplitter {

    /**
     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        // Calculate the center of the box
        Vec2 center = box.getCenter();

        // Create a new box to the right of the center
        Box2D rightBox = new Box2D(center.x + box.getWidth() / 2, center.y - box.getHeight() / 2, box.getWidth() / 2, box.getHeight());

        // Create a new box to the left of the center
        Box2D leftBox = new Box2D(center.x - box.getWidth() / 2, center.y - box.getHeight() / 2, box.getWidth() / 2, box.getHeight());

        return Pair.with(rightBox, leftBox);
    }
}

