    /**
     * @param modelName model name of the entity
     * @throws IllegalStateException if sharding key indices are not continuous
     */
    public void check(String modelName) throws IllegalStateException {
        if (modelNames == null) {
            throw new IllegalArgumentException("Model names cannot be null");
        }

        int lastKeyIndex = -1;
        for (String model : modelName.split(",")) {
            int keyIndex = model.indexOf('|');
            if (keyIndex == -1 || lastKeyIndex == -1 || keyIndex - lastKeyIndex != 1) {
                throw new IllegalStateException("Invalid sharding key index entry: " + model);
            }
            lastKeyIndex = keyIndex;
        }
    }
}

