private String unescapeId(String input) {
    String escapedId = input.replace("\\.", "\\."); // Replace '\\' to '\'
    Pattern pattern = Pattern.compile("\\\\[dg:.AFhIMPrvwxyz]");
    Matcher matcher = pattern.matcher(escapedId);
    StringBuffer unescapedId = new StringBuffer();
    while (matcher.find()) {
        matcher.appendReplacement(unescapedId, Matcher.group().replace("\\", ""));
    }
    matcher.appendTail(unescapedId);
    return unescapedId.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    if (array1 == null && array2 == null) {
        return null;
    }
    int length1 = array1 == null ? 0 : array1.length;
    int length2 = array2 == null ? 0 : array2.length;
    int totalLength = length1 + 2 * length2;

    String[] result = new String[totalLength];
    int index = 0;

    if (array1 != null) {
        System.arraycopy(array1, 0, result, index, length1);
        index += length1;
    }

    int overlapIndex = 0;
    for (String element : array2) {
        result[index++] = element;
        result[index++] = element;
        overlapIndex++;
    }

    return result;
}

