public class VertexMover {
    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        Set<Integer> emptyStockLabel = new HashSet<>();
        Collections.addAll(emptyStockLabel, minLabel == 0 ? 0 : 0, minLabel == 1 ? 1 : 0);

        List<Set<Integer>> updatedBuckets = new LinkedList<>();
        for (int label = 0; label < bucketsByLabel.size(); label++) {
            Set<Integer> bucket = bucketsByLabel.get(label);
            if (label == minLabel) {
                bucket.addAll(emptyStockLabel);
            }
            updatedBuckets.add(bucket);
        }

        bucketsByLabel = updatedBuckets;
        labels.clear();
    }
}

