class DoublyLinkedList<T> {
    ListNode<T> head;
    ListNode<T> tail;
    int size;

    public ListNode<T> getHead() {
        return head;
    }

    public ListNode<T> getTail() {
        return tail;
    }

    public int getSize() {
        return size;
    }

    public void addAtHead(T value) {
        ListNode<T> newNode = new ListNode<>(value);
        if (head == null) {
            head = tail = newNode;
        } else {
            newNode.next = head;
            head.prev = newNode;
            head = newNode;
        }
        size++;
    }

    public void addAtTail(T value) {
        ListNode<T> newNode = new ListNode<>(value);
        if (tail == null) {
            head = tail = newNode;
        } else {
            newNode.prev = tail;
            tail.next = newNode;
            tail = newNode;
        }
        size++;
    }

    public void removeListNode(ListNode<T> node) {
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }
        size--;
    }

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        while (!list.isEmpty()) {
            ListNode<T> node = list.removeAtHead();
            addAtTail(node.getValue());
        }
    }
}

