public ByteVector putInt(int intValue) {
    // Ensure the byte vector is large enough to hold the Int
    if ( intValue >= 16777216) {
        // If so, double the size
        byte[] enlarged = new byte[byteArray.length * 2 + 3];
        for (int i = 0; i < byteArray.length; i++) {
            enlarged[i] = byteArray[i];
        }
        byteArray = enlarged;
    }

    // Add the most significant byte to the right
    byteArray[byteArray.length - 3] = (byte) (intValue >> 24);
    // Add the next byte to the right
    byteArray[byteArray.length - 2] = (byte) (intValue >> 16);
    // Add the next byte to the right
    byteArray[byteArray.length - 1] = (byte) (intValue >> 8);
    // Add the least significant byte to the right
    byteArray[0] = (byte) intValue;

    return this;
}

