public class Graph {
    private Map<Node, List<Node>> graphMap;
    private CompositeNode parent;

    // Method to populate the graph
    public void initializeGraph() {
        // Example data
        if (graphMap == null) graphMap = new HashMap<>();
        Node n1 = new Node();
        Node n2 = new Node();
        Node n3 = new Node();
        Node n4 = new Node();
        graphMap.put(n1, new ArrayList<>(Arrays.asList(n2)));
        graphMap.put(n2, new ArrayList<>(Arrays.asList(n1, n3)));
        graphMap.put(n3, new ArrayList<>(Arrays.asList(n2, n4)));
        graphMap.put(n4, new ArrayList<>(Arrays.asList(n3)));
        parent = n1;
    }

    public Edge edgeToNext() {
        return edgeToNext(parent);
    }

    private Edge edgeToNext(Node currentNode) {
        List<Node> neighbors = Objects.requireNonNull(graphMap.get(currentNode));
        // Check for virtual nodes
        Node realNode = (neighbors.isEmpty()) ? parent : neighbors.get(0);
        // Connect to the next Node
        graphMap.get(realNode).add(currentNode);
        return new Edge(currentNode, realNode);
    }

    public static void main(String[] args) {
        Graph graph = new Graph();
        graph.initializeGraph();

        Edge edge = graph.edgeToNext(); // Returns an edge connecting previously returned node with node
        System.out.println("Edge: " + edge);
    }
}

